@app.route("/lab3", methods=["GET", "POST"])
def lab3():
    from flask import session
    if request.method == "GET":
        try:
            if "username" in session:
                return render_template(
                    "lab3.html", username=session["username"], success=True
                )
            return render_template("lab3.html")
        except:
            pass
        return render_template("lab3.html")

    elif request.method == "POST":
        if "username" not in request.form:
            session.clear()
            response = make_response(render_template("lab3.html"))
            return response

        username = request.form.get("username")
        password = request.form.get("password")
        password_hash = hashlib.sha256(password.encode()).hexdigest()

        if username in USERS and USERS[username]["password"] == password_hash:
            session["username"] = username
            session["role"] = USERS[username]["role"]

            response = make_response(
                render_template("lab3.html", success=True, username=username)
            )
            return response

        return render_template("lab3.html", failure=True)
